/* ✨ Intro screen: the GlowBop logo bursts to life with its sound logo when the console opens (laptop, iPad, iPhone).
   Phones and tablets only allow sound after a touch, so the screen waits for a tap when the browser blocks audio.
   Once per visit. SETUP → Intro screen: Sound / Silent / Off. */
(() => {
  const EV = [[0.35, "boot", [4, 4]], [0.454, "boot", [6, 2]], [0.557, "boot", [5, 4]], [0.661, "boot", [3, 3]], [0.765, "boot", [6, 2]], [0.869, "boot", [6, 4]], [0.973, "boot", [6, 3]], [1.076, "boot", [0, 4]], [1.18, "boot", [3, 1]], [1.4, "ring", 0], [1.51, "ring", 1], [1.62, "ring", 2], [1.73, "ring", 3], [1.92, "glint", [6, 2]], [1.99, "glint", [4, 1]], [2.06, "glint", [4, 3]], [2.2, "all", null], [2.7, "glint", [5, 5]], [2.95, "glint", [3, 6]], [3.2, "glint", [4, 6]], [3.5, "glint", [5, 2]], [3.9, "glint", [2, 0]]];
  const SND = 'data:audio/mpeg;base64,';
  const P = '#ff3d9a', V = '#9b3dff', C = '#33d6ff', W = '#ffffff', D = '#221d33';
  const M = [[D,D,C,C,C,D,D],[D,C,V,V,V,C,D],[C,V,P,P,P,V,C],[C,V,P,W,P,V,C],[C,V,P,P,P,V,C],[D,C,V,V,V,C,D],[D,D,C,C,C,D,D]];
  const RING = {[W]: 0, [P]: 1, [V]: 2, [C]: 3};
  const pref = () => { try { return localStorage.getItem('gb_intro') || 'sound'; } catch (e) { return 'sound'; } };
  const setPref = v => { try { localStorage.setItem('gb_intro', v); } catch (e) {} };
  const seen = () => { try { return sessionStorage.getItem('gb_intro_seen') === '1'; } catch (e) { return false; } };
  const markSeen = () => { try { sessionStorage.setItem('gb_intro_seen', '1'); } catch (e) {} };

  const css = `
  #gbIntro{position:fixed;inset:0;z-index:9999;background:radial-gradient(circle at 50% 45%,#1a1030 0,#07050d 70%);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:28px;transition:opacity .45s ease;cursor:pointer;-webkit-tap-highlight-color:transparent}
  #gbIntro.out{opacity:0;pointer-events:none}
  #gbIntro svg{width:min(62vw,52vh,340px);height:auto;overflow:visible;transform:scale(.62);transition:transform .25s cubic-bezier(.2,1.6,.4,1)}
  #gbIntro.go svg{transform:scale(.8)}
  #gbIntro.big svg{transform:scale(1.06);transition:transform .35s cubic-bezier(.2,1.5,.35,1)}
  #gbIntro.settle svg{transform:scale(1);transition:transform 1.2s ease}
  #gbIntro circle{transition:fill .12s,r .12s,opacity .12s}
  #gbIntro .tap{font:600 13px/1 system-ui,sans-serif;letter-spacing:.35em;color:#cfc6ff;opacity:.85;animation:gbiP 1.6s ease-in-out infinite;text-transform:uppercase}
  #gbIntro.go .tap{visibility:hidden}
  #gbIntro .word{font:800 18px/1 system-ui,sans-serif;letter-spacing:.5em;color:#fff;opacity:0;transition:opacity .6s}
  #gbIntro.big .word{opacity:.9}
  @keyframes gbiP{50%{opacity:.35}}
  @media (prefers-reduced-motion:reduce){#gbIntro svg{transition:none!important}}`;

  function show(mode) {
    const st = document.createElement('style'); st.textContent = css; document.head.appendChild(st);
    const el = document.createElement('div'); el.id = 'gbIntro'; el.setAttribute('role', 'dialog'); el.setAttribute('aria-label', 'GlowBop');
    let c = '';
    M.forEach((row, r) => row.forEach((col, k) => { c += `<circle cx="${9 + k * 13}" cy="${9 + r * 13}" r="4.6" fill="${col}" data-r="${r}" data-c="${k}" opacity="${col === D ? 1 : .14}"/>`; }));
    el.innerHTML = `<svg viewBox="0 0 96 96" aria-hidden="true"><defs><filter id="gbiG" x="-1" y="-1" width="3" height="3"><feGaussianBlur stdDeviation="2.4" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge></filter></defs><g filter="url(#gbiG)">${c}</g></svg>
      <div class="word">GLOWBOP</div><div class="tap">Tap to start</div>`;
    document.body.appendChild(el);
    const dot = (r, k) => el.querySelector(`circle[data-r="${r}"][data-c="${k}"]`);
    const lit = [...el.querySelectorAll('circle')].filter(n => M[+n.dataset.r][+n.dataset.c] !== D);
    const on = (n, o) => n.setAttribute('opacity', o);
    const glint = n => { const f = M[+n.dataset.r][+n.dataset.c]; n.setAttribute('fill', '#fff'); n.setAttribute('r', '5.8'); setTimeout(() => { n.setAttribute('fill', f); n.setAttribute('r', '4.6'); }, 280); };
    let started = false, ctx = null, buf = null;
    const finish = () => { el.classList.add('out'); setTimeout(() => { el.remove(); st.remove(); }, 500); };
    const run = withSound => {
      if (started) return; started = true; markSeen(); el.classList.add('go');
      if (withSound && ctx && buf) { try { const s = ctx.createBufferSource(); s.buffer = buf; s.connect(ctx.destination); s.start(); } catch (e) {} }
      EV.forEach(([t, a, d]) => setTimeout(() => {
        if (a === 'boot') { const n = dot(d[0], d[1]); if (n && n.getAttribute('opacity') < 0.35) on(n, .35); }
        else if (a === 'ring') lit.forEach(n => { if (RING[M[+n.dataset.r][+n.dataset.c]] <= d) on(n, 1); });
        else if (a === 'glint') { const n = dot(d[0], d[1]); if (n) { on(n, 1); glint(n); } }
        else if (a === 'all') { lit.forEach(n => { on(n, 1); glint(n); }); el.classList.add('big'); setTimeout(() => el.classList.add('settle'), 380); }
      }, t * 1000));
      setTimeout(finish, 4500);
    };
    el.addEventListener('click', () => { if (started) return finish(); prime().then(() => run(mode === 'sound')); });
    async function prime() {
      if (mode !== 'sound') return;
      try {
        ctx = ctx || new (window.AudioContext || window.webkitAudioContext)();
        if (ctx.state === 'suspended') await ctx.resume();
        if (!buf) { const ab = await (await fetch(SND)).arrayBuffer(); buf = await new Promise((ok, no) => ctx.decodeAudioData(ab, ok, no)); }
      } catch (e) {}
    }
    if (mode === 'silent') { setTimeout(() => run(false), 250); return; }
    // sound: start by itself when the browser allows audio, otherwise wait for the tap
    prime().then(() => { if (ctx && ctx.state === 'running' && buf) setTimeout(() => run(true), 150); });
    setTimeout(() => { if (!started) { /* still waiting for a tap: fine */ } }, 0);
  }

  const embedded = (() => { try { return window.top !== window || /[?&]embed=/.test(location.search); } catch (e) { return true; } })();
  const mode = pref();
  if (mode !== 'off' && !seen() && !embedded) {
    if (document.body) show(mode); else document.addEventListener('DOMContentLoaded', () => show(mode));
  }

  // SETUP → Intro screen
  const addPanel = () => GB.panel('setup', 57, el => {
    el.classList.add('box'); el.style.setProperty('--c', 'var(--pink)');
    el.innerHTML = `<div class="ph"><span>Intro screen</span></div>
      <div class="seg" id="introSeg" style="display:flex;gap:6px"></div>
      <p class="note">The GlowBop logo bursts to life with its sound when the console opens. Phones and tablets need one tap to allow sound.</p>
      <button class="btn sm" id="introTry" style="margin-top:8px">Play it now</button>`;
    const seg = el.querySelector('#introSeg');
    [['sound', 'Sound'], ['silent', 'Silent'], ['off', 'Off']].forEach(([k, n]) => {
      const b = document.createElement('button'); b.className = 'btn sm'; b.style.flex = '1'; b.textContent = n; b.dataset.k = k;
      b.onclick = () => { setPref(k); paint(); }; seg.appendChild(b);
    });
    const paint = () => seg.querySelectorAll('button').forEach(b => b.classList.toggle('on', b.dataset.k === pref()));
    el.querySelector('#introTry').onclick = () => { if (!document.getElementById('gbIntro')) show(pref() === 'off' ? 'sound' : pref()); };
    paint();
  });
  if (window.GB && GB.panel) addPanel(); else document.addEventListener('DOMContentLoaded', () => window.GB && GB.panel && addPanel());
})();
